def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [r for r in range(h) if any(v != bg for v in grid[r])]

    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    if len(bands) < 2:
        return [row[:] for row in grid]

    upper, lower = bands[0], bands[1]
    n = min(len(upper), len(lower))

    U = {(rr, c) for rr in range(n) for c in range(w)
         if grid[upper[rr]][c] != bg}
    L = {(rr, c) for rr in range(n) for c in range(w)
         if grid[lower[rr]][c] != bg}

    best_dx, best_score = 0, -1
    for dx in range(-w + 1, w):
        score = sum((r, c + dx) in L for r, c in U if 0 <= c + dx < w)
        if score > best_score or (score == best_score and abs(dx) < abs(best_dx)):
            best_dx, best_score = dx, score

    out = [row[:] for row in grid]
    if best_dx > 0:
        source, dest, shift = upper, lower, best_dx
    elif best_dx < 0:
        source, dest, shift = lower, upper, -best_dx
    else:
        return out

    for rr in range(n):
        for c in range(w):
            if grid[source[rr]][c] != bg:
                nc = c + shift
                if nc < w and grid[dest[rr]][nc] == bg:
                    out[dest[rr]][nc] = 1

    return out
